from pathlib import Path
p=Path('Source/LarGridPivot.Grid.pas')
s=p.read_text(encoding='utf-8')
s=s.replace('LarGridPivot.Engine, LarGridPivot.LayoutEngine, LarGridPivot.ViewInfo;','LarGridPivot.Engine, LarGridPivot.LayoutEngine, LarGridPivot.ViewInfo, LarGridPivot.PrintConfig;')
s=s.replace('    FPrintShowPageNumbers:Boolean;','    FPrintShowPageNumbers:Boolean;\n    FPrintOptions:TLarPivotPrintOptions;')
s=s.replace('    procedure GridPrintPreviewClick(Sender:TObject);','    procedure GridPrintPreviewClick(Sender:TObject);\n    procedure GridPageSetupClick(Sender:TObject);')
s=s.replace('    procedure PrintPreview;','    procedure PrintPreview;\n    procedure ConfigurePrint;')
s=s.replace('    property PrintShowPageNumbers:Boolean read FPrintShowPageNumbers write FPrintShowPageNumbers default True;','    property PrintShowPageNumbers:Boolean read FPrintShowPageNumbers write FPrintShowPageNumbers default True;\n    property PrintOptions:TLarPivotPrintOptions read FPrintOptions;')
s=s.replace('    FPrev, FNext, FPrint, FClose: TButton;','    FPrev, FNext, FPrint, FSetup, FClose: TButton;')
s=s.replace(" FPrint:=TButton.Create(Self); FPrint.Parent:=FTopPanel; FPrint.SetBounds(440,8,90,28); FPrint.Caption:='Imprimir...'; FPrint.OnClick:=PrintClick;\n FClose:=TButton.Create(Self); FClose.Parent:=FTopPanel; FClose.SetBounds(536,8,80,28);", " FSetup:=TButton.Create(Self); FSetup.Parent:=FTopPanel; FSetup.SetBounds(440,8,110,28); FSetup.Caption:='Configurar...'; FSetup.OnClick:=procedure(Sender:TObject) begin FPivot.ConfigurePrint; FPageCount:=FPivot.PrintPageCount(1120,790,FPaint.Canvas); UpdateState; end;\n FPrint:=TButton.Create(Self); FPrint.Parent:=FTopPanel; FPrint.SetBounds(556,8,90,28); FPrint.Caption:='Imprimir...'; FPrint.OnClick:=PrintClick;\n FClose:=TButton.Create(Self); FClose.Parent:=FTopPanel; FClose.SetBounds(652,8,80,28);")
# Delphi anonymous event above is invalid for TNotifyEvent in older Delphi; replace with named method
s=s.replace('    procedure PrintClick(Sender:TObject);','    procedure PrintClick(Sender:TObject);\n    procedure SetupClick(Sender:TObject);')
s=s.replace("FSetup.OnClick:=procedure(Sender:TObject) begin FPivot.ConfigurePrint; FPageCount:=FPivot.PrintPageCount(1120,790,FPaint.Canvas); UpdateState; end;",'FSetup.OnClick:=SetupClick;')
s=s.replace('procedure TLarPivotPrintPreviewForm.PrintClick(Sender:TObject); begin FPivot.PrintPivotDialog; end;','procedure TLarPivotPrintPreviewForm.PrintClick(Sender:TObject); begin FPivot.PrintPivotDialog; end;\nprocedure TLarPivotPrintPreviewForm.SetupClick(Sender:TObject); begin FPivot.ConfigurePrint; FPageCount:=FPivot.PrintPageCount(1120,790,FPaint.Canvas); UpdateState; end;')
s=s.replace("FAllowCellSelection:=True; FAllowMultiSelect:=True; FAllowCopyToClipboard:=True; FPrintTitle:=''; FPrintLandscape:=True; FPrintShowPageNumbers:=True; TabStop:=True;", "FAllowCellSelection:=True; FAllowMultiSelect:=True; FAllowCopyToClipboard:=True; FPrintTitle:=''; FPrintLandscape:=True; FPrintShowPageNumbers:=True; FPrintOptions:=TLarPivotPrintOptions.Create(Self); TabStop:=True;")
s=s.replace('destructor TLarGridPivot.Destroy; begin SaveAutoLayout;', 'destructor TLarGridPivot.Destroy; begin SaveAutoLayout; FPrintOptions.Free;')
# margins
s=s.replace('TopM:=Round(AHeight*0.04); BottomM:=AHeight-TopM;', 'TopM:=Round(AHeight*(FPrintOptions.MarginTopMM/297.0)); BottomM:=AHeight-Round(AHeight*(FPrintOptions.MarginBottomMM/297.0));')
s=s.replace('LeftM:=Round(AWidth*0.04); RightM:=AWidth-LeftM; TopM:=Round(AHeight*0.04); BottomM:=AHeight-TopM;', 'LeftM:=Round(AWidth*(FPrintOptions.MarginLeftMM/210.0)); RightM:=AWidth-Round(AWidth*(FPrintOptions.MarginRightMM/210.0)); TopM:=Round(AHeight*(FPrintOptions.MarginTopMM/297.0)); BottomM:=AHeight-Round(AHeight*(FPrintOptions.MarginBottomMM/297.0));')
s=s.replace('if TotalW>0 then Scale:=Min(1.0,AvailW/TotalW) else Scale:=1.0;', 'if FPrintOptions.FitToPageWidth and (TotalW>0) then Scale:=Min(1.0,AvailW/TotalW) else Scale:=1.0;')
# custom widths for row and data columns
s=s.replace('W:=Round(RFs[I].Width*Scale);', "if FPrintOptions.Columns.Find(RFs[I].FieldName)<>nil then W:=FPrintOptions.Columns.Find(RFs[I].FieldName).Width else W:=0; if W<=0 then W:=RFs[I].Width; W:=Round(W*Scale);")
s=s.replace('W:=Round(FLayoutEngine.Columns[D].Width*Scale);', "if (FLayoutEngine.Columns[D].DataField<>nil) and (FPrintOptions.Columns.Find(FLayoutEngine.Columns[D].DataField.FieldName)<>nil) then W:=FPrintOptions.Columns.Find(FLayoutEngine.Columns[D].DataField.FieldName).Width else W:=0; if W<=0 then W:=FLayoutEngine.Columns[D].Width; W:=Round(W*Scale);")
# menu setup
s=s.replace("AddItem('Vista previa de impresión...',GridPrintPreviewClick);", "AddItem('Vista previa de impresión...',GridPrintPreviewClick);\n AddItem('Configurar impresión...',GridPageSetupClick);")
# methods
anchor='procedure TLarGridPivot.GridPrintPreviewClick(Sender:TObject);\nbegin\n PrintPreview;\nend;'
insert=anchor+'''\n\nprocedure TLarGridPivot.GridPageSetupClick(Sender:TObject);\nbegin ConfigurePrint; end;\n\nprocedure TLarGridPivot.ConfigurePrint;\nvar F:TForm; CPaper:TComboBox; ELeft,ERight,ETop,EBottom:TEdit; CFit:TCheckBox; BOK,BCancel:TButton; L:TLabel; I,Y:Integer; PCol:TLarPivotPrintColumn;\nbegin\n F:=TForm.CreateNew(Self);\n try\n  F.Caption:='Configurar impresión'; F.Position:=poScreenCenter; F.Width:=430; F.Height:=420; F.BorderStyle:=bsDialog;\n  L:=TLabel.Create(F); L.Parent:=F; L.SetBounds(16,18,120,20); L.Caption:='Tamaño de papel:';\n  CPaper:=TComboBox.Create(F); CPaper.Parent:=F; CPaper.Style:=csDropDownList; CPaper.SetBounds(150,14,230,24); CPaper.Items.Add('Predeterminado'); CPaper.Items.Add('A4'); CPaper.Items.Add('Carta'); CPaper.Items.Add('A5'); CPaper.Items.Add('Legal'); CPaper.ItemIndex:=Ord(FPrintOptions.PaperSize);\n  Y:=56;\n  for I:=0 to 3 do begin L:=TLabel.Create(F); L.Parent:=F; L.Left:=16; L.Top:=Y+4; case I of 0:L.Caption:='Margen izquierdo (mm):'; 1:L.Caption:='Margen derecho (mm):'; 2:L.Caption:='Margen superior (mm):'; 3:L.Caption:='Margen inferior (mm):'; end; case I of 0:begin ELeft:=TEdit.Create(F); ELeft.Parent:=F; ELeft.Text:=IntToStr(FPrintOptions.MarginLeftMM); ELeft.SetBounds(200,Y,70,24); end; 1:begin ERight:=TEdit.Create(F); ERight.Parent:=F; ERight.Text:=IntToStr(FPrintOptions.MarginRightMM); ERight.SetBounds(200,Y,70,24); end; 2:begin ETop:=TEdit.Create(F); ETop.Parent:=F; ETop.Text:=IntToStr(FPrintOptions.MarginTopMM); ETop.SetBounds(200,Y,70,24); end; 3:begin EBottom:=TEdit.Create(F); EBottom.Parent:=F; EBottom.Text:=IntToStr(FPrintOptions.MarginBottomMM); EBottom.SetBounds(200,Y,70,24); end; end; Inc(Y,34); end;\n  CFit:=TCheckBox.Create(F); CFit.Parent:=F; CFit.SetBounds(16,Y+4,280,24); CFit.Caption:='Ajustar columnas al ancho de página'; CFit.Checked:=FPrintOptions.FitToPageWidth; Inc(Y,38);\n  L:=TLabel.Create(F); L.Parent:=F; L.SetBounds(16,Y,360,20); L.Caption:='Anchos de impresión (0 = ancho del grid):'; Inc(Y,24);\n  for I:=0 to FFields.Count-1 do if FFields[I].Area in [paRow,paData] then begin PCol:=FPrintOptions.Columns.Ensure(FFields[I].FieldName); L:=TLabel.Create(F); L.Parent:=F; L.SetBounds(20,Y+4,180,20); L.Caption:=FFields[I].Caption; with TEdit.Create(F) do begin Parent:=F; Name:='PrintWidth'+IntToStr(I); Tag:=I; Text:=IntToStr(PCol.Width); SetBounds(210,Y,70,24); end; Inc(Y,28); if Y>315 then Break; end;\n  BOK:=TButton.Create(F); BOK.Parent:=F; BOK.Caption:='Aceptar'; BOK.ModalResult:=mrOk; BOK.Default:=True; BOK.SetBounds(210,345,80,28); BCancel:=TButton.Create(F); BCancel.Parent:=F; BCancel.Caption:='Cancelar'; BCancel.ModalResult:=mrCancel; BCancel.SetBounds(300,345,80,28);\n  if F.ShowModal=mrOk then begin FPrintOptions.PaperSize:=TLarPivotPaperSize(CPaper.ItemIndex); FPrintOptions.MarginLeftMM:=StrToIntDef(ELeft.Text,12); FPrintOptions.MarginRightMM:=StrToIntDef(ERight.Text,12); FPrintOptions.MarginTopMM:=StrToIntDef(ETop.Text,12); FPrintOptions.MarginBottomMM:=StrToIntDef(EBottom.Text,12); FPrintOptions.FitToPageWidth:=CFit.Checked; for I:=0 to F.ComponentCount-1 do if (F.Components[I] is TEdit) and (F.Components[I].Tag>=0) and (Pos('PrintWidth',F.Components[I].Name)=1) then begin PCol:=FPrintOptions.Columns.Ensure(FFields[F.Components[I].Tag].FieldName); PCol.Width:=StrToIntDef(TEdit(F.Components[I]).Text,0); end; end;\n finally F.Free; end;\nend;'''
s=s.replace(anchor,insert)
p.write_text(s,encoding='utf-8')
